from collections import Counter, deque

def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    background = Counter(v for row in grid for v in row).most_common(1)[0][0]
    exterior = set()
    q = deque()
    for r in range(h):
        for c in (0, w - 1):
            if grid[r][c] == background and (r, c) not in exterior:
                exterior.add((r, c)); q.append((r, c))
    for c in range(w):
        for r in (0, h - 1):
            if grid[r][c] == background and (r, c) not in exterior:
                exterior.add((r, c)); q.append((r, c))
    while q:
        r, c = q.popleft()
        for rr, cc in ((r-1,c),(r+1,c),(r,c-1),(r,c+1)):
            if 0 <= rr < h and 0 <= cc < w and grid[rr][cc] == background and (rr,cc) not in exterior:
                exterior.add((rr,cc)); q.append((rr,cc))
    for r in range(h):
        for c in range(w):
            if grid[r][c] == background and (r,c) not in exterior:
                out[r][c] = 4
    return out

